 * following symlinks) to a trusted system directory. This prevents picking up
 * an attacker-controlled `rg` from the working directory or another untrusted
 * location.
 *
 * @returns The resolved binary path, or null if no trusted binary is found.
 */
export async function resolveRipgrepPath(): Promise<string | null> {
  const platform = os.platform();
  const arch = os.arch();

  // Map to the correct bundled binary
  const binName = `rg-${platform}-${arch}${platform === 'win32' ? '.exe' : ''}`;

  const candidatePaths = [
    // 1. SEA runtime layout: everything is flattened into the root dir
    path.resolve(__dirname, 'vendor/ripgrep', binName),
    // 2. Dev/Dist layout: packages/core/dist/tools/ripGrep.js -> packages/core/vendor/ripgrep
    path.resolve(__dirname, '../../vendor/ripgrep', binName),
  ];

  for (const candidate of candidatePaths) {
    if (await fileExists(candidate)) {
      return candidate;
    }
  }

  // No bundled binary was found. Fall back to a system-installed `rg`.
  const systemPath = await resolveExecutable('rg');
  if (!systemPath) {
    return null;
  }

  try {
    const realPath = resolveToRealPath(systemPath);
    if (isTrustedSystemPath(realPath)) {
      return realPath;
    }
  } catch {
    // If we cannot resolve the real path, treat it as untrusted.
    return null;
  }

  return null;
